from pathlib import Path
legacy='''<details class="login-card legacy-card"><summary>老朋友（尚未綁定udn會員）<i class="ph ph-caret-down" aria-hidden="true"></i></summary><p class="legacy-copy">因應業務移轉，未來僅提供綁定 udn 會員帳號完整服務。請選擇您原有登入方式，並儘速完成 udn 會員綁定。</p><div class="legacy-auth"><button class="udn" data-auth-provider="udn" aria-label="使用原有 udn 帳號綁定"><img src="assets/login-udn.svg" alt=""></button><button data-auth-provider="Google" aria-label="使用原有 Google 帳號綁定"><img src="assets/login-google.svg" alt=""></button><button class="mobile" data-auth-provider="手機號碼" aria-label="使用原有手機號碼綁定"><i class="ph ph-device-mobile" aria-hidden="true"></i><small>手機號碼</small></button><button class="facebook" data-auth-provider="Facebook" aria-label="使用原有 Facebook 帳號綁定"><img src="assets/login-facebook.svg" alt=""></button><button class="apple" data-auth-provider="Apple" aria-label="使用原有 Apple 帳號綁定"><img src="assets/login-apple.svg" alt=""></button></div></details>'''
sheet='''<div id="login-method-overlay" hidden><section class="login-method-sheet" role="dialog" aria-modal="true" aria-labelledby="login-method-title"><div class="login-method-header"><button id="login-method-close" aria-label="關閉會員登入方式"><i class="ph ph-caret-down" aria-hidden="true"></i></button><h2 id="login-method-title">會員登入</h2></div><div class="login-method-body"><h3>請選擇登入方式</h3><button class="auth-option" data-auth-provider="E-mail／手機"><img src="assets/login-udn.svg" alt="">使用 E-mail / 手機登入</button><div class="auth-divider">OR</div><button class="auth-option facebook" data-auth-provider="Facebook"><img src="assets/login-facebook.svg" alt="">使用Facebook登入</button><button class="auth-option" data-auth-provider="Google"><img src="assets/login-google.svg" alt="">使用Google登入</button><button class="auth-option apple" data-auth-provider="Apple"><img src="assets/login-apple.svg" alt="">使用 Apple 登入</button><button class="auth-option line" data-auth-provider="Line"><img src="assets/login-line.svg" alt="">使用Line登入</button></div></section></div>'''
for name in ['index.html','settings-panel.html']:
 p=Path(name);s=p.read_text(encoding='utf-8');start=s.index('<details class="login-card">');end=s.index('</details>',start)+len('</details>');s=s[:start]+legacy+s[end:]
 if name=='index.html':
  s=s.replace('<div class="toast"',sheet+'<div class="toast"');s=s.replace('<link rel="stylesheet" href="css/terms-browser.css">','<link rel="stylesheet" href="css/terms-browser.css"><link rel="stylesheet" href="css/login-sheet.css">');s=s.replace('<script src="js/terms-browser.js"></script>','<script src="js/terms-browser.js"></script><script src="js/login-sheet.js"></script>')
 p.write_text(s,encoding='utf-8')
p=Path('js/settings.js');s=p.read_text(encoding='utf-8').replace("    if(e.target.closest('[data-login-preview]'))toast('會員服務尚未連線，請先使用訪客登入');",'');p.write_text(s,encoding='utf-8')
